#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
# the header line and the other booking stay
grep -q '^# room' "$t" || { echo "header line lost"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking lost"; fail=1; }
# not found: exit 1, nothing on stdout, the message on stderr
so=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
[ $rc = 1 ] || { echo "not found should exit 1, got $rc"; fail=1; }
[ -z "$so" ] || { echo "not found wrote to stdout: $so"; fail=1; }
se=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null)
[ "$se" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found stderr: $se"; fail=1; }
# wrong number of arguments: exit 2, usage on stderr, nothing on stdout
so=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>/dev/null); rc=$?
[ $rc = 2 ] || { echo "usage should exit 2, got $rc"; fail=1; }
[ -z "$so" ] || { echo "usage wrote to stdout: $so"; fail=1; }
se=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null)
[ "$se" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage stderr: $se"; fail=1; }
# same date and start in another room: only the named room's booking goes
r=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$r"
BOOKINGS=$r bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel in same slot failed"; fail=1; }
grep -q '^kaede.2026-01-05.09:00' "$r" || { echo "other room's booking removed"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$r" || { echo "aoi booking still there after cancel"; fail=1; }
rm -f "$t" "$r"; exit $fail

